// Project-authored headless shim over the vendored ares SFC core (ISC).
//
// Exposes the same C ABI as the LakeSnes shims (crates/oracle/src/lib.rs
// `ffi` module) so the Rust boundary is unchanged: init/load/run/buttons/
// state + WRAM/VRAM/CGRAM/APU-RAM/CPU-PC accessors.
//
// The system pak (boards.bml + the SPC IPL) is injected from a header
// generated by crates/oracle/build.rs: "ares-embedded-data.hpp".

#include <ares/ares.hpp>
#include <sfc/sfc.hpp>
#include <nall/vfs.hpp>
#include <nall/hash/sha256.hpp>

#include <ares-embedded-data.hpp>

#include <cstdint>
#include <cstring>
#include <span>
#include <vector>

namespace ares::SuperFamicom {
  auto load(Node::System&, string) -> bool;
  auto option(string, string) -> bool;
}

using namespace ares;

namespace {

struct OraclePlatform : ares::Platform {
  std::shared_ptr<vfs::directory> systemPak;
  std::vector<u8> romBytes;
  string bootTitle;
  string bootRegion;
  string bootBoard;

  bool buttonState[12] = {};

  u32 width = 0;
  u32 height = 0;
  std::vector<u32> lastFrame;

  bool systemAttached = false;
  auto pak(Node::Object node) -> std::shared_ptr<vfs::directory> override {
    (void)node;
    if(!systemAttached) {
      systemAttached = true;
      return systemPak;
    }
    auto cart = std::make_shared<vfs::directory>();
    cart->setAttribute("title", bootTitle);
    cart->setAttribute("region", bootRegion);
    cart->setAttribute("board", bootBoard);
    cart->append("program.rom", std::span<const u8>{romBytes.data(), romBytes.size()});
    cart->append("save.ram", 8 * 1024);
    return cart;
  }

  auto video(Node::Video::Screen, const u32* data, u32 pitch, u32 width, u32 height) -> void override {
    // Convert the ares RGB30 screen into an internal XRGB8888 image.
    this->width = width;
    this->height = height;
    lastFrame.assign((std::size_t)width * height, 0);
    u32 sourceX = width > 512 ? (width - 512) / 2 : 0;
    u32 copyWidth = width > 512 ? 512 : width;
    u32 copyHeight = height > 480 ? 480 : height;
    u32 sourceY = height > 480 ? (height - 480) / 2 : 0;
    for(u32 y = 0; y < copyHeight; y++) {
      const u32* src = data + (y + sourceY) * (pitch >> 2) + sourceX;
      for(u32 x = 0; x < copyWidth; x++) {
        u32 v = src[x];
        u32 r = (v >> 20) & 0x3ff;
        u32 g = (v >> 10) & 0x3ff;
        u32 b = (v >> 0) & 0x3ff;
        u32 p = (b >> 2) | ((g >> 2) << 8) | ((r >> 2) << 16);
        lastFrame[y * width + x] = p;
      }
    }
  }

  auto input(Node::Input::Input node) -> void override {
    static constexpr const char* names[12] = {
      "B", "Y", "Select", "Start", "Up", "Down", "Left", "Right", "A", "X", "L", "R",
    };
    auto name = node->name();
    for(u32 id : range(12)) {
      if(name == names[id]) {
        auto button = node->cast<Node::Input::Button>();
        if(button) button->setValue(buttonState[id]);
        return;
      }
    }
  }

  auto audio(Node::Audio::Stream) -> void override {}
};

class OracleCore;

namespace {
OracleCore* singletonCore = nullptr;
}

class OracleCore {
public:
  OraclePlatform platform;
  Node::System root;
  u32 frames = 0;
  bool loaded = false;

  OracleCore() {
    platform.systemPak = std::make_shared<vfs::directory>();
    platform.systemPak->append("boards.bml", std::span<const u8>{gBoardsBml, gBoardsBmlSize});
    platform.systemPak->append("ipl.rom", std::span<const u8>{gIplRom, 64});
  }

  bool loadRom(const u8* data, u32 length) {
    if(root && root->name()) {
      // Full teardown before reload: the ares core is a process singleton.
      root->unload();
    }
    root = {};
    platform.romBytes.assign(data, data + length);
    // Region sniff from the SNES internal header.
    bool pal = platform.romBytes.size() > 0xffd9 && platform.romBytes[0xffd9] == 2;
    platform.bootRegion = pal ? "PAL" : "NTSC";
    platform.bootTitle = "Terranigma";
    platform.bootBoard = "SHVC-1J3M-20";

    SuperFamicom::option("Pixel Accuracy", true);
    SuperFamicom::option("Deterministic Entropy", true);

    ares::platform = (ares::Platform*)&platform;
    bool ok = SuperFamicom::load(root, string{"[Nintendo] Super Famicom (", platform.bootRegion, ")"});
    if(!ok) return false;

    if(auto port = root->find<Node::Port>("Cartridge Slot")) {
      auto cartridge = port->allocate();
      port->connect();
    } else {
      return false;
    }
    if(auto port = root->find<Node::Port>("Controller Port 1")) {
      auto device = port->allocate("Gamepad");
      port->connect();
    }
    root->power();
    return true;
  }
};

}  // namespace

extern "C" {

typedef struct Snes Snes;

// The ares core is a process singleton (globals + threads inside the
// vendored engine) and cannot be destroyed and rebuilt safely, so exactly
// one `OracleCore` ever lives. `snes_free` is a no-op; a second
// `snes_loadRom` (after the first session leaked a fresh core) fails
// cleanly rather than corrupting the engine. Any second boot requires a
// new process, which is how the test suite runs its cross-boot checks.
Snes* snes_init(void) {
  if(!singletonCore) singletonCore = new OracleCore();
  return (Snes*)singletonCore;
}

void snes_free(Snes* snes) {
  delete (OracleCore*)snes;
}

void snes_reset(Snes* snes, bool hard) {
  (void)snes;
  (void)hard;
}

bool snes_loadRom(Snes* snes, const uint8_t* data, int length) {
  if(!snes || !data || length <= 0) return false;
  auto* core = (OracleCore*)snes;
  if(core->loaded) return false;  // one boot per process; see snes_init
  bool ok = core->loadRom(data, (u32)length);
  if(ok) core->loaded = true;
  return ok;
}

void snes_runFrame(Snes* snes) {
  auto* core = (OracleCore*)snes;
  core->root->run();
  core->frames++;
}

void snes_setPixelFormat(Snes* snes, int pixelFormat) {
  (void)snes;
  (void)pixelFormat;
}

void snes_setPixels(Snes* snes, uint8_t* pixelData) {
  auto& pl = ((OracleCore*)snes)->platform;
  if(pl.lastFrame.empty()) return;
  for(u32 y = 0; y < pl.height && y < 480; y++) {
    for(u32 x = 0; x < pl.width && x < 512; x++) {
      u32 v = pl.lastFrame[y * pl.width + x];
      std::size_t offset = ((std::size_t)y * 512 + x) * 4;
      pixelData[offset + 0] = v & 0xff;
      pixelData[offset + 1] = (v >> 8) & 0xff;
      pixelData[offset + 2] = (v >> 16) & 0xff;
      pixelData[offset + 3] = 0;
    }
  }
}

void snes_setSamples(Snes* snes, int16_t* sampleData, int samplesPerFrame) {
  (void)snes;
  (void)sampleData;
  (void)samplesPerFrame;
}

void snes_setButtonState(Snes* snes, int player, int button, bool pressed) {
  (void)player;
  if(!snes || button < 0 || button > 11) return;
  ((OracleCore*)snes)->platform.buttonState[button] = pressed;
}

int snes_saveState(Snes* snes, uint8_t* data) {
  auto& core = *(OracleCore*)snes;
  auto s = core.root->serialize(true);
  auto size = s.size();
  // 4-byte shim frame counter prefix so state round-trips fully.
  if(data && size + 4 <= (u32)4 * 1024 * 1024) {
    uint32_t f = core.frames;
    std::memcpy(data, &f, 4);
    std::memcpy(data + 4, s.data(), size);
  }
  return (int)size + 4;
}

bool snes_loadState(Snes* snes, const uint8_t* data, int size) {
  auto& core = *(OracleCore*)snes;
  if(size < 4) return false;
  uint32_t f = 0;
  std::memcpy(&f, data, 4);
  core.frames = f;
  auto s = serializer{data + 4, (u32)size - 4};
  return core.root->unserialize(s);
}

const uint8_t* snes_ram(const Snes* snes) {
  (void)snes;
  return (const uint8_t*)SuperFamicom::cpu.wram;
}

uint32_t snes_frames(const Snes* snes) {
  return ((const OracleCore*)snes)->frames;
}

uint64_t snes_cycles(const Snes* snes) {
  (void)snes;
  return 0;
}

const uint16_t* snes_vram(const Snes* snes) {
  (void)snes;
  return (const uint16_t*)SuperFamicom::ppuImpl.vram.data;
}

const uint16_t* snes_cgram(const Snes* snes) {
  (void)snes;
  return (const uint16_t*)SuperFamicom::ppuImpl.cgram;
}

uint16_t snes_cpu_pc(const Snes* snes) {
  (void)snes;
  return SuperFamicom::cpu.r.pc.w;
}

uint8_t snes_cpu_bank(const Snes* snes) {
  (void)snes;
  return SuperFamicom::cpu.r.b;
}

const uint8_t* snes_apu_ram(const Snes* snes) {
  (void)snes;
  return (const uint8_t*)SuperFamicom::dsp.apuram;
}

}  // extern "C"
